SELECT p.id AS product_id, p.name, p.grade, p.charge_name AS productChargeName, pi.project_status, p.brand_name, pi.id AS projectId, p.grade_id, p.charge_id AS productChargeId, p.project_charge_id AS projectChargeId, p.type, p.approval_status, pi.charge_name AS projectChargeName, p.create_time, p.progress_status, p.image_url, p.property, p.category, pi.end_time, pph.name as projectPhase FROM product_info p LEFT JOIN project_info pi ON p.id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id LEFT JOIN project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE P.delete_state = 0 AND p.is_finished_product_dev = 1 AND p.is_deleted = FALSE
AND p.category_id IN
#{categoryId}
AND (P.name LIKE concat('%',#{params.searchKeyword},'%') OR p.id IN (SELECT pd.product_id FROM product_detail pd WHERE pd.sku_no LIKE concat('%',#{params.searchKeyword},'%')) OR p.spu_no LIKE concat('%',#{params.searchKeyword},'%'))
AND P.approval_status IN
#{state}
AND P.id IN
#{productId}
AND P.id NOT IN
#{productId}
AND p.grade_id IN
#{gradeId}
AND p.brand_id IN
#{brandId}
AND p.progress_status IN
#{progressStatus}
AND pi.charge_id IN
#{chargeId}
AND p.property_id IN
#{propertyId}
AND pph.name IN
#{phaseName}
AND
string_to_array(#{chargeId},',') && string_to_array(p.charge_id,',')
AND p.create_time >=#{params.startTime}
AND p.create_time <= #{params.endTime}
AND (p.id IN (SELECT pt.product_id FROM project_task pt WHERE 1 = 1 ${params.param}) )
ORDER BY p.create_time DESC

